ALTER TABLE public.progress_bills ADD COLUMN IF NOT EXISTS bill_date date;
ALTER TABLE public.progress_bills ADD COLUMN IF NOT EXISTS due_date date;
ALTER TABLE public.progress_bills ADD COLUMN IF NOT EXISTS terms text;
ALTER TABLE public.progress_bills ADD COLUMN IF NOT EXISTS client_notes text;
ALTER TABLE public.progress_bills ADD COLUMN IF NOT EXISTS internal_notes text;
ALTER TABLE public.progress_bills ADD COLUMN IF NOT EXISTS bill_type text NOT NULL DEFAULT 'progress' CHECK(bill_type IN ('materials','progress','holdback','final'));
ALTER TABLE public.progress_bills ADD COLUMN IF NOT EXISTS gst_pct numeric;
CREATE OR REPLACE FUNCTION public.bill_activity() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.project_stage; label text; BEGIN SELECT stage INTO s FROM public.projects WHERE id=NEW.project_id; label:=CASE WHEN TG_OP='INSERT' THEN 'Draft created' WHEN NEW.status='issued' AND OLD.status IS DISTINCT FROM NEW.status THEN 'Issued' WHEN NEW.status='void' AND OLD.status IS DISTINCT FROM NEW.status THEN 'Voided' ELSE 'Draft saved' END; INSERT INTO public.project_stage_events(project_id,from_stage,to_stage,changed_by,note) VALUES(NEW.project_id,s,s,auth.uid(),NEW.number||' · '||label); RETURN NEW; END; $$;
DROP TRIGGER IF EXISTS bill_activity ON public.progress_bills;
CREATE TRIGGER bill_activity AFTER INSERT OR UPDATE ON public.progress_bills FOR EACH ROW EXECUTE FUNCTION public.bill_activity();
CREATE OR REPLACE FUNCTION public.set_progress_bill_status(_id uuid,_to text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b public.progress_bills; held_after bigint; released bigint; BEGIN SELECT project_id INTO b.project_id FROM public.progress_bills WHERE id=_id; IF NOT FOUND THEN RAISE EXCEPTION 'Bill not found'; END IF; IF NOT public.has_capability('manage_projects',b.project_id) OR NOT public.has_capability('view_pricing',b.project_id) THEN RAISE EXCEPTION 'Managing projects and pricing access are required to change bills'; END IF; PERFORM pg_advisory_xact_lock(hashtext('progress_bills'||b.project_id::text)); SELECT * INTO b FROM public.progress_bills WHERE id=_id FOR UPDATE; IF _to='void' AND b.status='issued' AND b.kind='progress' THEN SELECT coalesce(sum(holdback_cents) FILTER(WHERE kind='progress' AND status='issued' AND id<>_id),0),coalesce(sum(gross_cents) FILTER(WHERE kind='holdback_release' AND status<>'void'),0) INTO held_after,released FROM public.progress_bills WHERE project_id=b.project_id; IF released>held_after THEN RAISE EXCEPTION 'Holdback from this bill has already been released. Void the holdback release first.'; END IF; END IF; IF _to='issued' AND b.status='draft' THEN UPDATE public.progress_bills SET status='issued',issued_at=now() WHERE id=_id; ELSIF _to='void' AND b.status='issued' THEN UPDATE public.progress_bills SET status='void' WHERE id=_id; ELSIF _to='deleted' AND b.status='draft' THEN DELETE FROM public.progress_bills WHERE id=_id; ELSE RAISE EXCEPTION 'A % bill cannot be changed to %.',b.status,_to; END IF; END; $$;
CREATE OR REPLACE FUNCTION public.save_bill_draft(_id uuid,_bill jsonb,_issue boolean DEFAULT false,_copy boolean DEFAULT false,_confirm_over boolean DEFAULT false) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b public.progress_bills; p public.projects; target uuid; n int; gross bigint; hold bigint; net bigint; tax bigint; hb numeric; gst numeric; contract bigint; billed bigint; held bigint; released bigint; d date; due date; line_data jsonb; typ text; BEGIN SELECT project_id INTO b.project_id FROM public.progress_bills WHERE id=_id; IF NOT FOUND THEN RAISE EXCEPTION 'Bill not found'; END IF; IF NOT public.has_capability('manage_projects',b.project_id) OR NOT public.has_capability('view_pricing',b.project_id) THEN RAISE EXCEPTION 'Managing projects and pricing access are required to edit bills'; END IF; PERFORM pg_advisory_xact_lock(hashtext('progress_bills'||b.project_id::text)); SELECT * INTO b FROM public.progress_bills WHERE id=_id FOR UPDATE; IF NOT _copy AND b.status<>'draft' THEN RAISE EXCEPTION 'Only drafts can be edited'; END IF; SELECT * INTO p FROM public.projects WHERE id=b.project_id; d:=(_bill->>'bill_date')::date; due:=nullif(_bill->>'due_date','')::date; IF d IS NULL OR (due IS NOT NULL AND due<d) THEN RAISE EXCEPTION 'Due date must be on or after bill date'; END IF; hb:=(_bill->>'holdback_pct')::numeric; IF hb IS NULL OR hb<0 OR hb>50 THEN RAISE EXCEPTION 'Holdback must be between 0 and 50 percent'; END IF; IF b.kind='holdback_release' THEN hb:=0; END IF; typ:=coalesce(_bill->>'bill_type','progress'); IF typ NOT IN ('materials','progress','holdback','final') OR (b.kind='holdback_release' AND typ<>'holdback') OR (b.kind='progress' AND typ='holdback') THEN RAISE EXCEPTION 'Invalid bill kind'; END IF; IF jsonb_typeof(_bill->'lines') IS DISTINCT FROM 'array' OR jsonb_array_length(_bill->'lines')=0 THEN RAISE EXCEPTION 'Add at least one line'; END IF; IF EXISTS(SELECT 1 FROM jsonb_array_elements(_bill->'lines') l WHERE btrim(coalesce(l->>'description',''))='' OR coalesce((l->>'quantity')::numeric,0)<=0 OR coalesce((l->>'unitPriceCents')::bigint,0)<=0 OR btrim(coalesce(l->>'unit',''))='') THEN RAISE EXCEPTION 'Each line needs a description, unit, quantity and price above zero'; END IF; SELECT jsonb_agg(l||jsonb_build_object('amountCents',round((l->>'quantity')::numeric*(l->>'unitPriceCents')::bigint))),sum(round((l->>'quantity')::numeric*(l->>'unitPriceCents')::bigint)) INTO line_data,gross FROM jsonb_array_elements(_bill->'lines') l; IF gross<=0 THEN RAISE EXCEPTION 'Amount must be above zero'; END IF; hold:=round(gross*hb/100); net:=gross-hold; SELECT gst_pct INTO gst FROM public.tax_settings WHERE id=1; gst:=coalesce(gst,5); tax:=round(net*gst/100); SELECT coalesce(sum(accepted_value_cents),0) INTO contract FROM public.quotes WHERE project_id=b.project_id AND status='accepted'; SELECT coalesce(sum(gross_cents) FILTER(WHERE kind='progress'),0),coalesce(sum(holdback_cents) FILTER(WHERE kind='progress' AND status='issued'),0),coalesce(sum(gross_cents) FILTER(WHERE kind='holdback_release'),0) INTO billed,held,released FROM public.progress_bills WHERE project_id=b.project_id AND status<>'void' AND (_copy OR id<>_id); IF b.kind='holdback_release' AND gross>held-released THEN RAISE EXCEPTION 'The bill exceeds available holdback'; END IF; IF b.kind='progress' AND p.contract_type<>'open_book' AND net>greatest(contract-billed,0) AND NOT _confirm_over THEN RAISE EXCEPTION 'Confirm over-billing: net exceeds Left to bill'; END IF;
IF _copy THEN SELECT coalesce(max(seq),0)+1 INTO n FROM public.progress_bills WHERE project_id=b.project_id; INSERT INTO public.progress_bills(project_id,seq,number,kind,lines,gross_cents,holdback_pct,holdback_cents,net_cents,gst_cents,total_cents,open_book) VALUES(b.project_id,n,coalesce(p.project_number||'-','')||'B'||lpad(n::text,2,'0'),b.kind,line_data,gross,hb,hold,net,tax,net+tax,b.open_book) RETURNING id INTO target; ELSE target:=_id; END IF;
UPDATE public.progress_bills SET period_note=nullif(btrim(_bill->>'period_note'),''),lines=line_data,gross_cents=gross,holdback_pct=hb,holdback_cents=hold,net_cents=net,gst_cents=tax,total_cents=net+tax,gst_pct=gst,bill_date=d,due_date=due,terms=nullif(_bill->>'terms',''),client_notes=nullif(_bill->>'client_notes',''),internal_notes=nullif(_bill->>'internal_notes',''),bill_type=typ WHERE id=target; IF _issue THEN PERFORM public.set_progress_bill_status(target,'issued'); END IF; RETURN target; END; $$;
REVOKE ALL ON FUNCTION public.save_bill_draft(uuid,jsonb,boolean,boolean,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.save_bill_draft(uuid,jsonb,boolean,boolean,boolean) TO authenticated;
NOTIFY pgrst,'reload schema';